WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount NULLS LAST, id) AS latest_rank FROM orders QUALIFY latest_rank = 1) SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, store_id, COUNT(*) FILTER (WHERE status = 'COMPLETED') AS completed_rows, COUNT(DISTINCT store_id) AS distinct_store_ids, GROUPING(DATE_TRUNC('MONTH', order_date)) AS grouping_level FROM deduped GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', order_date), store_id), (DATE_TRUNC('MONTH', order_date)), ()) ORDER BY completed_rows DESC
